        "cpp": "/*\n너비 우선 탐색 (BFS) - 최단거리 (일반 그래프)\n- 백준 난이도: 실버 I\n방향 벡터가 없는 일반적인 인접 리스트 형태의 그래프에서 시작점부터 목표점까지의 최단 거리를 구하는 알고리즘입니다.\n모든 간선의 길이가 같을 때 최단 거리를 찾는 데 최적화되어 있습니다.\n시간 복잡도: O(V + E)\n\n[입력 예시]\n4 5 1\n1 2\n1 3\n1 4\n2 4\n3 4\n\n[출력 예시]\n1 2 3 4\n*/\n\n#include <iostream>\n#include <vector>\n#include <queue>\n\nusing namespace std;\n\nvector<int> graph_adj[100001];\nint distArr[100001];\n\nvoid bfs(int start_node) {\n    queue<int> q;\n    q.push(start_node);\n    distArr[start_node] = 0;\n\n    while (!q.empty()) {\n        int curr = q.front();\n        q.pop();\n\n        for (int adj : graph_adj[curr]) {\n            if (distArr[adj] == -1) {\n                distArr[adj] = distArr[curr] + 1;\n                q.push(adj);\n            }\n        }\n    }\n}\n\nint main() {\n    ios_base::sync_with_stdio(false);\n    cin.tie(NULL);\n\n    // 데이터 입력\n    int n, m, start;\n    cin >> n >> m >> start;\n    for (int i = 0; i <= n; i++) distArr[i] = -1;\n\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        cin >> a >> b;\n        graph_adj[a].push_back(b);\n        graph_adj[b].push_back(a);\n    }\n\n    // 문제 해결 로직\n    bfs(start);\n\n    // 결과 출력\n    for (int i = 1; i <= n; i++) cout << distArr[i] << \"\\n\";\n\n    return 0;\n}\n"
