        "python": "'''\n깊이 우선 탐색 (DFS) - 연결요소\n- 백준 난이도: 실버 II\n스택 또는 재귀함수를 이용하여 그래프의 깊은 부분을 먼저 탐색하는 알고리즘입니다.\n그래프 전체를 깊게 탐색할 때 사용하는 경로 찾기/연결 요소 세기 알고리즘.\n시간 복잡도: O(V + E)\n\n[입력 예시]\n4 5 1\n1 2\n1 3\n1 4\n2 4\n3 4\n\n[출력 예시]\n1 2 4 3\n'''\nimport sys\nsys.setrecursionlimit(10**5)\n\ndef dfs(x, y, n, m, graph):\n    if x <= -1 or x >= n or y <= -1 or y >= m:\n        return False\n    if graph[x][y] == 0:\n        graph[x][y] = 1\n        dfs(x - 1, y, n, m, graph)\n        dfs(x, y - 1, n, m, graph)\n        dfs(x + 1, y, n, m, graph)\n        dfs(x, y + 1, n, m, graph)\n        return True\n    return False\n\nn, m = map(int, sys.stdin.readline().split())\ngraph = []\n\nfor _ in range(n):\n    graph.append(list(map(int, list(sys.stdin.readline().rstrip()))))\n    \nresult = 0\nfor i in range(n):\n    for j in range(m):\n        if dfs(i, j, n, m, graph):\n            result += 1\n\nprint(result)\n",
        "cpp": "/*\n깊이 우선 탐색 (DFS) - 연결요소\n- 백준 난이도: 실버 II\n스택 또는 재귀함수를 이용하여 그래프의 깊은 부분을 먼저 탐색하는 알고리즘입니다.\n그래프 전체를 깊게 탐색할 때 사용하는 경로 찾기/연결 요소 세기 알고리즘.\n시간 복잡도: O(V + E)\n\n[입력 예시]\n4 5 1\n1 2\n1 3\n1 4\n2 4\n3 4\n\n[출력 예시]\n1 2 4 3\n*/\n\n#include <iostream>\n#include <vector>\n#include <string>\n\nusing namespace std;\n\nint n, m;\nvector<vector<int>> grid;\n\nbool dfs(int x, int y) {\n    if (x <= -1 || x >= n || y <= -1 || y >= m) return false;\n    if (grid[x][y] == 0) {\n        grid[x][y] = 1;\n        dfs(x - 1, y);\n        dfs(x, y - 1);\n        dfs(x + 1, y);\n        dfs(x, y + 1);\n        return true;\n    }\n    return false;\n}\n\nint main() {\n    ios_base::sync_with_stdio(false);\n    cin.tie(NULL);\n\n    // 데이터 입력\n    cin >> n >> m;\n    grid.assign(n, vector<int>(m, 0));\n    for (int i = 0; i < n; i++) {\n        string row;\n        cin >> row;\n        for (int j = 0; j < m; j++) grid[i][j] = row[j] - '0';\n    }\n\n    // 문제 해결 로직\n    int result = 0;\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < m; j++) {\n            if (dfs(i, j)) result++;\n        }\n    }\n\n    // 결과 출력\n    cout << result << \"\\n\";\n\n    return 0;\n}\n"
