        "fileName": "CCW",
        "python": "'''\n[문제 제목]: CCW (Counter Clockwise)\n- 백준 난이도: 골드 V\n- 문제 설명: 평면 위에 놓인 세 점의 방향 관계를 결정합니다. 세 점 A, B, C가 순서대로 있을 때 반시계 방향이면 1, 시계 방향이면 -1, 일직선이면 0을 반환합니다.\n- 시간 복잡도: O(1)\n\n[입력 예시]\n1 1\n5 5\n7 3\n\n[출력 예시]\n-1\n'''\nimport sys\ninput = sys.stdin.readline\n\n# 데이터 입력\nx1, y1 = map(int, input().split())\nx2, y2 = map(int, input().split())\nx3, y3 = map(int, input().split())\n\n# 문제 해결 로직\ndef ccw(x1, y1, x2, y2, x3, y3):\n    res = (x1 * y2 + x2 * y3 + x3 * y1) - (y1 * x2 + y2 * x3 + y3 * x1)\n    if res > 0: return 1\n    elif res < 0: return -1\n    else: return 0\n\nresult = ccw(x1, y1, x2, y2, x3, y3)\n\n# 결과 출력\nprint(result)\n",
        "cpp": "/*\n[문제 제목]: CCW (Counter Clockwise)\n- 백준 난이도: 골드 V\n- 문제 설명: 평면 위에 놓인 세 점의 방향 관계를 결정합니다. 세 점 A, B, C가 순서대로 있을 때 반시계 방향이면 1, 시계 방향이면 -1, 일직선이면 0을 반환합니다.\n- 시간 복잡도: O(1)\n\n[입력 예시]\n1 1\n5 5\n7 3\n\n[출력 예시]\n-1\n*/\n\n#include <iostream>\n\nusing namespace std;\n\nint ccw(long long x1, long long y1, long long x2, long long y2, long long x3, long long y3) {\n    long long res = (x1 * y2 + x2 * y3 + x3 * y1) - (y1 * x2 + y2 * x3 + y3 * x1);\n    if (res > 0) return 1;\n    else if (res < 0) return -1;\n    else return 0;\n}\n\nint main() {\n    ios_base::sync_with_stdio(false);\n    cin.tie(NULL);\n\n    // 데이터 입력\n    long long x1, y1, x2, y2, x3, y3;\n    cin >> x1 >> y1;\n    cin >> x2 >> y2;\n    cin >> x3 >> y3;\n\n    // 문제 해결 로직\n    int result = ccw(x1, y1, x2, y2, x3, y3);\n\n    // 결과 출력\n    cout << result << \"\\n\";\n\n    return 0;\n}\n"
