        "python": "'''\n2차원 배열 누적 합 (2D Prefix Sum)\n- 백준 난이도: 실버 I\n2차원 격자에서 지정된 특정 직사각형 영역의 합을 O(1) 시간만에 빠르게 계산하는 알고리즘.\n\n[입력 예시]\n5 3\n1 2\n2 3\n3 4\n4 5\n\n[출력 예시]\n1\n2\n3 4 5\n'''\nimport sys\n\nn, m = map(int, sys.stdin.readline().split())\ngraph = [list(map(int, sys.stdin.readline().split())) for _ in range(n)]\n\nprefix_2d = [[0] * (n + 1) for _ in range(n + 1)]\n\nfor i in range(1, n + 1):\n    for j in range(1, n + 1):\n        prefix_2d[i][j] = graph[i - 1][j - 1] + prefix_2d[i - 1][j] + prefix_2d[i][j - 1] - prefix_2d[i - 1][j - 1]\n\nfor _ in range(m):\n    r1, c1, r2, c2 = map(int, sys.stdin.readline().split())\n    result = prefix_2d[r2][c2] - prefix_2d[r1 - 1][c2] - prefix_2d[r2][c1 - 1] + prefix_2d[r1 - 1][c1 - 1]\n    print(result)\n",
        "cpp": "/*\n2차원 배열 누적 합 (2D Prefix Sum)\n- 백준 난이도: 실버 I\n2차원 격자에서 지정된 특정 직사각형 영역의 합을 O(1) 시간만에 빠르게 계산하는 알고리즘.\n\n[입력 예시]\n5 3\n1 2\n2 3\n3 4\n4 5\n\n[출력 예시]\n1\n2\n3 4 5\n*/\n\n#include <iostream>\n#include <vector>\n\nusing namespace std;\n\nint main() {\n    ios_base::sync_with_stdio(false);\n    cin.tie(NULL);\n\n    // 데이터 입력\n    int n, m;\n    cin >> n >> m;\n    vector<vector<long long>> graph(n, vector<long long>(n));\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) {\n            cin >> graph[i][j];\n        }\n    }\n\n    // 문제 해결 로직\n    vector<vector<long long>> prefix_2d(n + 1, vector<long long>(n + 1, 0));\n    for (int i = 1; i <= n; i++) {\n        for (int j = 1; j <= n; j++) {\n            prefix_2d[i][j] = graph[i - 1][j - 1] + prefix_2d[i - 1][j] + prefix_2d[i][j - 1] - prefix_2d[i - 1][j - 1];\n        }\n    }\n\n    // 결과 출력\n    for (int q = 0; q < m; q++) {\n        int r1, c1, r2, c2;\n        cin >> r1 >> c1 >> r2 >> c2;\n        long long result = prefix_2d[r2][c2] - prefix_2d[r1 - 1][c2] - prefix_2d[r2][c1 - 1] + prefix_2d[r1 - 1][c1 - 1];\n        cout << result << \"\\n\";\n    }\n\n    return 0;\n}\n"
