        "cpp": "/*\n최장 증가 부분 수열 (LIS) - O(N log N) 이분 탐색 활용\n- 백준 난이도: 골드 II\n단순 DP O(N^2)로 풀 수 없는 배열의 길이가 매우 긴 경우, 이분 탐색을 결합하여 시간 복잡도를 O(N log N)으로 단축시키는 알고리즘입니다.\n\n[입력 예시]\n6\n10 20 10 30 20 50\n\n[출력 예시]\n4\n*/\n\n#include <iostream>\n#include <vector>\n#include <algorithm>\n\nusing namespace std;\n\nint main() {\n    ios_base::sync_with_stdio(false);\n    cin.tie(NULL);\n\n    // 데이터 입력\n    int n;\n    cin >> n;\n    vector<int> arr(n);\n    for (int i = 0; i < n; i++) cin >> arr[i];\n\n    // 문제 해결 로직\n    vector<int> dp;\n    dp.push_back(arr[0]);\n\n    for (int i = 1; i < n; i++) {\n        if (arr[i] > dp.back()) {\n            dp.push_back(arr[i]);\n        } else {\n            int idx = lower_bound(dp.begin(), dp.end(), arr[i]) - dp.begin();\n            dp[idx] = arr[i];\n        }\n    }\n\n    // 결과 출력\n    cout << dp.size() << \"\\n\";\n\n    return 0;\n}\n"
