        "cpp": "/*\n무한 배낭 문제 (Unbounded Knapsack Problem)\n- 백준 난이도: 골드 V\n각 물건의 개수 제한이 무한대일 때, 버틸 수 있는 무게 내에서 가치의 최댓값을 구하는 알고리즘.\n0/1 1차원 배낭과 유사하지만, 중복을 허용해야 하므로 무게를 앞에서부터(정방향) 탐색합니다.\n\n[입력 예시]\n5 3\n1 2\n2 3\n3 4\n4 5\n\n[출력 예시]\n1\n2\n3 4 5\n*/\n\n#include <iostream>\n#include <vector>\n#include <algorithm>\n\nusing namespace std;\n\nint main() {\n    ios_base::sync_with_stdio(false);\n    cin.tie(NULL);\n\n    // 데이터 입력\n    int n, k;\n    cin >> n >> k;\n\n    // 문제 해결 로직\n    vector<long long> dp(k + 1, 0);\n    for (int i = 0; i < n; i++) {\n        int w, v;\n        cin >> w >> v;\n        for (int j = w; j <= k; j++) {\n            dp[j] = max(dp[j], dp[j - w] + v);\n        }\n    }\n\n    // 결과 출력\n    cout << dp[k] << \"\\n\";\n\n    return 0;\n}\n"
