        "cpp": "/*\n[문제 제목]: KMP (Knuth-Morris-Pratt) 알고리즘\n- 백준 난이도: 골드 I\n- 문제 설명: 문자열 내에서 특정 패턴을 효율적으로 찾는 알고리즘입니다. '실패 함수(Failure Function)'를 통해 패턴 내의 접두사와 접미사가 일치하는 최대 길이를 미리 계산하여 매칭 실패 시 불필요한 비교를 건너뜁니다.\n- 시간 복잡도: O(N+M)\n\n[입력 예시]\nababacaba\nabacaba\n\n[출력 예시]\n1\n3\n*/\n\n#include <iostream>\n#include <vector>\n#include <string>\n\nusing namespace std;\n\nstring strip_str(const string& s) {\n    size_t start = s.find_first_not_of(\" \\t\\r\\n\");\n    if (start == string::npos) return \"\";\n    size_t end = s.find_last_not_of(\" \\t\\r\\n\");\n    return s.substr(start, end - start + 1);\n}\n\nint main() {\n    ios_base::sync_with_stdio(false);\n    cin.tie(NULL);\n\n    // 데이터 입력\n    string text, pattern;\n    getline(cin, text);\n    getline(cin, pattern);\n    text = strip_str(text);\n    pattern = strip_str(pattern);\n\n    // 문제 해결 로직\n    vector<int> result;\n    if (!text.empty() && !pattern.empty()) {\n        int m = pattern.size();\n        vector<int> pi(m, 0);\n        int j = 0;\n\n        for (int i = 1; i < m; i++) {\n            while (j > 0 && pattern[i] != pattern[j]) {\n                j = pi[j - 1];\n            }\n            if (pattern[i] == pattern[j]) {\n                j++;\n                pi[i] = j;\n            }\n        }\n\n        int n = text.size();\n        j = 0;\n\n        for (int i = 0; i < n; i++) {\n            while (j > 0 && text[i] != pattern[j]) {\n                j = pi[j - 1];\n            }\n            if (text[i] == pattern[j]) {\n                if (j == m - 1) {\n                    result.push_back(i - m + 2);\n                    j = pi[j];\n                } else {\n                    j++;\n                }\n            }\n        }\n    }\n\n    // 결과 출력\n    if (!text.empty() && !pattern.empty()) {\n        cout << result.size() << \"\\n\";\n        for (int res : result) cout << res << \"\\n\";\n    }\n\n    return 0;\n}\n"
