        "python": "'''\n트라이 (Trie / Prefix Tree)\n- 백준 난이도: 골드 V\n문자열을 효율적으로 저장하고 탐색하기 위한 트리 형태의 자료구조입니다.\n자동 완성, 사전 검색 등에서 활용되며, 탐색 시간 복잡도는 문자열의 길이(L)에 비례하는 O(L)입니다.\n\n[입력 예시]\n5\napple\napply\nant\nbanana\nband\napple\n\n[출력 예시]\n1\n'''\nimport sys\n\nclass TrieNode:\n    def __init__(self):\n        # 자식 노드들을 딕셔너리나 고정 배열로 저장\n        self.children = {}\n        # 해당 노드에서 끝나는 문자열이 있는지 여부\n        self.is_end = False\n\nclass Trie:\n    def __init__(self):\n        self.root = TrieNode()\n\n    def insert(self, word):\n        node = self.root\n        for char in word:\n            if char not in node.children:\n                node.children[char] = TrieNode()\n            node = node.children[char]\n        node.is_end = True\n\n    def search(self, word):\n        node = self.root\n        for char in word:\n            if char not in node.children:\n                return False\n            node = node.children[char]\n        return node.is_end\n\nif __name__ == \"__main__\":\n    trie = Trie()\n    input_data = sys.stdin.read().split()\n    if input_data:\n        n = int(input_data[0])\n        # n개의 단어 삽입\n        for i in range(1, n + 1):\n            trie.insert(input_data[i])\n        \n        # 마지막 단어 매칭 확인\n        search_word = input_data[n + 1]\n        print(1 if trie.search(search_word) else 0)\n",
        "cpp": "/*\n트라이 (Trie / Prefix Tree)\n- 백준 난이도: 골드 V\n문자열을 효율적으로 저장하고 탐색하기 위한 트리 형태의 자료구조입니다.\n자동 완성, 사전 검색 등에서 활용되며, 탐색 시간 복잡도는 문자열의 길이(L)에 비례하는 O(L)입니다.\n\n[입력 예시]\n5\napple\napply\nant\nbanana\nband\napple\n\n[출력 예시]\n1\n*/\n\n#include <iostream>\n#include <vector>\n#include <string>\n#include <map>\n\nusing namespace std;\n\nstruct TrieNode {\n    // 자식 노드들을 map으로 저장 (Python의 dict에 대응)\n    map<char, int> children;\n    // 해당 노드에서 끝나는 문자열이 있는지 여부\n    bool is_end = false;\n};\n\nstruct Trie {\n    vector<TrieNode> nodes;\n\n    Trie() { nodes.push_back(TrieNode()); } // index 0 = root\n\n    void insert(const string& word) {\n        int node = 0;\n        for (char c : word) {\n            if (nodes[node].children.find(c) == nodes[node].children.end()) {\n                nodes[node].children[c] = nodes.size();\n                nodes.push_back(TrieNode());\n            }\n            node = nodes[node].children[c];\n        }\n        nodes[node].is_end = true;\n    }\n\n    bool search(const string& word) {\n        int node = 0;\n        for (char c : word) {\n            auto it = nodes[node].children.find(c);\n            if (it == nodes[node].children.end()) return false;\n            node = it->second;\n        }\n        return nodes[node].is_end;\n    }\n};\n\nint main() {\n    ios_base::sync_with_stdio(false);\n    cin.tie(NULL);\n\n    // 데이터 입력\n    int n;\n    cin >> n;\n    vector<string> words(n);\n    for (int i = 0; i < n; i++) cin >> words[i];\n    string search_word;\n    cin >> search_word;\n\n    // 문제 해결 로직\n    Trie trie;\n    for (const string& word : words) trie.insert(word);\n    bool found = trie.search(search_word);\n\n    // 결과 출력\n    cout << (found ? 1 : 0) << \"\\n\";\n\n    return 0;\n}\n"
