        "python": "'''\n이진 탐색 (Binary Search)\n- 백준 난이도: 실버 II\n정렬된 배열 내에서 찾아야 할 값을 반으로 나누어가며 탐색하는 알고리즘.\n시간 복잡도: O(log N)\n\n[입력 예시]\n5 3\n1 2\n2 3\n3 4\n4 5\n\n[출력 예시]\n1\n2\n3 4 5\n'''\nimport sys\n\ndef binary_search(array, target, start, end):\n    while start <= end:\n        mid = (start + end) // 2\n        if array[mid] == target:\n            return mid\n        elif array[mid] > target:\n            end = mid - 1\n        else:\n            start = mid + 1\n    return None\n\nn, target = map(int, sys.stdin.readline().split())\narray = list(map(int, sys.stdin.readline().split()))\n\nresult = binary_search(array, target, 0, n - 1)\nif result == None:\n    print(\"Not Found\")\nelse:\n    print(result + 1)\n",
        "cpp": "/*\n이진 탐색 (Binary Search)\n- 백준 난이도: 실버 II\n정렬된 배열 내에서 찾아야 할 값을 반으로 나누어가며 탐색하는 알고리즘.\n시간 복잡도: O(log N)\n\n[입력 예시]\n5 3\n1 2\n2 3\n3 4\n4 5\n\n[출력 예시]\n1\n2\n3 4 5\n*/\n\n#include <iostream>\n#include <vector>\n\nusing namespace std;\n\nint binarySearch(vector<int>& array, int target, int start, int end) {\n    while (start <= end) {\n        int mid = (start + end) / 2;\n        if (array[mid] == target) return mid;\n        else if (array[mid] > target) end = mid - 1;\n        else start = mid + 1;\n    }\n    return -1;\n}\n\nint main() {\n    ios_base::sync_with_stdio(false);\n    cin.tie(NULL);\n\n    // 데이터 입력\n    int n, target;\n    cin >> n >> target;\n    vector<int> array(n);\n    for (int i = 0; i < n; i++) cin >> array[i];\n\n    // 문제 해결 로직\n    int result = binarySearch(array, target, 0, n - 1);\n\n    // 결과 출력\n    if (result == -1) cout << \"Not Found\" << \"\\n\";\n    else cout << result + 1 << \"\\n\";\n\n    return 0;\n}\n"
